```json
{
  "findings": [
    {
      "rule_id": "sql-injection",
      "severity": "error",
      "path": "src/login.js",
      "line": 9,
      "message": "SQL query is built via string concatenation with user-controlled input (`username`), allowing SQL injection. Use parameterized queries / prepared statements instead.",
      "evidence": "const query = \"SELECT * FROM users WHERE username = '\" + username + \"' AND active = 1\";"
    },
    {
      "rule_id": "hardcoded-secret",
      "severity": "error",
      "path": "src/login.js",
      "line": 14,
      "message": "Hardcoded API key committed to source code. Move secrets to environment variables or a secrets manager and rotate this key.",
      "evidence": "const SERVICE_API_KEY = \"sk-fixture-9f8e7d6c5b4a3f2e1d0c\";"
    },
    {
      "rule_id": "xss",
      "severity": "error",
      "path": "src/render.js",
      "line": 5,
      "message": "User-controlled content (`user.bio`) is injected directly into innerHTML without sanitization/escaping, enabling stored XSS. Use textContent or sanitize the HTML with a library such as DOMPurify.",
      "evidence": "document.getElementById(\"profile\").innerHTML = user.bio;"
    }
  ]
}
```

